DECLARE @counts TABLE ([table_name] nvarchar(128), [actual] bigint, [minimum] int);
INSERT INTO @counts SELECT N''''auth_user'''', COUNT_BIG(*), 5 FROM [auth_user];
INSERT INTO @counts SELECT N''''lichca_assignment'''', COUNT_BIG(*), 5 FROM [lichca_assignment];
INSERT INTO @counts SELECT N''''lichca_branch'''', COUNT_BIG(*), 5 FROM [lichca_branch];
INSERT INTO @counts SELECT N''''lichca_employee'''', COUNT_BIG(*), 5 FROM [lichca_employee];
INSERT INTO @counts SELECT N''''lichca_employeebranch'''', COUNT_BIG(*), 5 FROM [lichca_employeebranch];
INSERT INTO @counts SELECT N''''lichca_evidence'''', COUNT_BIG(*), 5 FROM [lichca_evidence];
INSERT INTO @counts SELECT N''''lichca_evidencetype'''', COUNT_BIG(*), 5 FROM [lichca_evidencetype];
INSERT INTO @counts SELECT N''''lichca_managerbranch'''', COUNT_BIG(*), 5 FROM [lichca_managerbranch];
INSERT INTO @counts SELECT N''''lichca_position'''', COUNT_BIG(*), 5 FROM [lichca_position];
INSERT INTO @counts SELECT N''''lichca_positionrequirement'''', COUNT_BIG(*), 5 FROM [lichca_positionrequirement];
INSERT INTO @counts SELECT N''''lichca_schedulegate'''', COUNT_BIG(*), 1 FROM [lichca_schedulegate];
INSERT INTO @counts SELECT N''''lichca_shift'''', COUNT_BIG(*), 5 FROM [lichca_shift];
INSERT INTO @counts SELECT N''''lichca_sundaybaseline'''', COUNT_BIG(*), 5 FROM [lichca_sundaybaseline];
INSERT INTO @counts SELECT N''''lichca_swaprequest'''', COUNT_BIG(*), 5 FROM [lichca_swaprequest];
IF EXISTS (SELECT 1 FROM @counts WHERE [actual]<[minimum])
    THROW 51000, ''''Insufficient mock rows. Import rolled back.'''', 1;
IF (SELECT COUNT(*) FROM [lichca_schedulegate])<>1 OR NOT EXISTS (SELECT 1 FROM [lichca_schedulegate] WHERE [id]=1)
    THROW 51000, ''''ScheduleGate must have exactly one row id=1.'''', 1;
SELECT @created AS [created_records], @attached AS [attached_accounts];
SELECT *, N''''OK'''' AS [result] FROM @counts ORDER BY [table_name];
PRINT N''''DATA READY: schema and full mock data verified. Accounts need local passwords. Application YC/T checks remain separate.'''';'';
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
    DECLARE @error nvarchar(2048)=CONCAT(@stage, N'' line '', ERROR_LINE(), N'': '', ERROR_MESSAGE());
    THROW 51000, @error, 1;
END CATCH;
';
EXEC sys.sp_executesql @install;
